float number(jass::Real value){return std::bit_cast<float>(value.bits());}
void zeppelinReachability(const wchar_t* root,const wchar_t* map,int journey=0){
    Archives archives(root);archives.mountMap(map);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.audioSimulationClock();session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();session.advance(4);auto& vm=session.runtime();auto& ai=*session.ais()[0];auto& avm=*ai.runtime;std::vector<std::uint32_t> existingShops;for(auto& [id,u]:session.units()){if(u->owner==0)u->paused=true;if(ObjectData::name(u->type)=="ngad")existingShops.push_back(id);}for(auto id:existingShops)vm.invoke("RemoveUnit",std::array{vm.handle("unit",id)});auto real=[&](int value){return vm.real(jass::Real::fromInteger(value));};auto spawn=[&](unsigned owner,const char* type,int x,int y){return vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000+owner),vm.integer(int(ObjectData::code(type))),real(x),real(y),real(0)});};auto buyer=spawn(0,"hpea",8765,1932),island=spawn(15,"ngad",3599,2077),land=spawn(15,"ngad",-7904,2080);auto unit=session.units().at(buyer.bits),remote=session.units().at(island.bits),seller=session.units().at(land.bits);auto& path=*session.world();auto movement=pathMovement(unit->movementType);if(path.pathRegionsNear({unit->x,unit->y},{remote->x,remote->y},unit->collision,movement,512)!=false || path.pathRegionsNear({unit->x,unit->y},{seller->x,seller->y},unit->collision,movement,512)!=true)throw std::runtime_error("Laboratory reachability fixture differs");for(auto shop:{island,land})vm.invoke("AddUnitToStock",std::array{shop,vm.integer(int(ObjectData::code("nzep"))),vm.integer(1),vm.integer(1)});for(int field:{1,2,4,6})vm.invoke("SetPlayerState",std::array{vm.handle("player",0x100000),vm.handle("playerstate",field),vm.integer(field<4?10000:200)});vm.invoke("ShowUnit",std::array{land,vm.boolean(false)});auto revision=unit->combat.revision;avm.invoke("PurchaseZeppelin");if(ai.zeppelinPurchase || unit->combat.revision!=revision || unit->currentOrder)throw std::runtime_error("Unreachable laboratory changed the buyer's orders");vm.invoke("ShowUnit",std::array{land,vm.boolean(true)});avm.invoke("GetZeppelin");avm.invoke("SingleMeleeAttack",std::array{avm.boolean(false),avm.boolean(false),avm.boolean(false),avm.boolean(false)});if(!ai.zeppelinPurchase || ai.zeppelinPurchase->buyer!=buyer.bits || ai.zeppelinPurchase->shop!=land.bits)throw std::runtime_error("AI selected an unreachable laboratory instead of the reachable one");if(journey){unit->pathing=false;vm.invoke("SetUnitInvulnerable",std::array{buyer,vm.boolean(true)});if(journey==2){unit->moveSpeed={};auto deadline=ai.zeppelinPurchase->deadline;if(deadline<=session.simulationTime() || deadline>session.simulationTime()+600)throw std::runtime_error("Invalid purchase deadline");while(ai.zeppelinPurchase && session.simulationTime()<deadline+2)session.advance(1);if(ai.zeppelinPurchase)throw std::runtime_error("Motionless buyer kept the reservation beyond its deadline");std::cout<<"PASS stalled_zeppelin_trip_released\n";}else{auto start=session.simulationTime();bool bought=false;for(unsigned n=0;n<240 && !bought;++n){session.advance(1);for(auto& [id,u]:session.units())if(u->owner==0 && ObjectData::name(u->type)=="nzep" && number(u->life)>0)bought=true;if(!bought && session.simulationTime()-start>61 && !ai.zeppelinPurchase)throw std::runtime_error("Long reachable trip lost its buyer reservation");}if(!bought || session.simulationTime()-start<=60)throw std::runtime_error("Long reachable trip did not purchase after 60 seconds");std::cout<<"PASS long_zeppelin_trip elapsed="<<session.simulationTime()-start<<"\n";}}else{vm.invoke("RemoveUnit",std::array{land});session.advance(1.1);if(ai.zeppelinPurchase)throw std::runtime_error("Removed laboratory retained the buyer reservation");}if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS reachable_zeppelin_laboratory\n";
}
void zeppelinPurchase(const wchar_t* root,const wchar_t* map){
    Archives archives(root);archives.mountMap(map);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.audioSimulationClock();session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();session.advance(4);auto& vm=session.runtime();auto& ai=*session.ais()[0];auto& avm=*ai.runtime;auto real=[&](int value){return vm.real(jass::Real::fromInteger(value));};auto spawn=[&](unsigned owner,const char* type,int x,int y){return vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000+owner),vm.integer(int(ObjectData::code(type))),real(x),real(y),real(0)});};auto buyer=spawn(0,"hpea",8200,1500),shop=spawn(15,"ngad",9000,1500);vm.invoke("SetUnitInvulnerable",std::array{buyer,vm.boolean(true)});vm.invoke("AddUnitToStock",std::array{shop,vm.integer(int(ObjectData::code("nzep"))),vm.integer(1),vm.integer(1)});for(int field:{1,2,4,6})vm.invoke("SetPlayerState",std::array{vm.handle("player",0x100000),vm.handle("playerstate",field),vm.integer(field<4?10000:200)});avm.invoke("GetZeppelin");avm.invoke("SingleMeleeAttack",std::array{avm.boolean(false),avm.boolean(false),avm.boolean(false),avm.boolean(false)});if(!ai.zeppelinPurchase || ai.zeppelinPurchase->buyer!=buyer.bits || ai.zeppelinPurchase->shop!=shop.bits)throw std::runtime_error("AI did not send the buyer to the laboratory");for(int n=0;n<320;++n){session.advance(.25);for(auto& [id,u]:session.units())if(u->owner==0 && ObjectData::name(u->type)=="nzep" && number(u->life)>0){auto& stock=session.units().at(shop.bits)->stock;auto entry=std::find_if(stock.begin(),stock.end(),[](const auto& item){return !item.item && item.type==ObjectData::code("nzep");});if(ai.zeppelinPurchase || entry==stock.end() || entry->current!=0 || session.config().players[0].states.at(1)>=10000 || GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Zeppelin purchase did not consume stock and gold or release reservation");std::cout<<"PASS ai_zeppelin_purchase time="<<session.simulationTime()<<"\n";return;}}throw std::runtime_error("AI did not buy the Zeppelin");
}
void islandWave(const wchar_t* root,const wchar_t* map,bool slow=false){
    Archives archives(root);archives.mountMap(map);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.audioSimulationClock();session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();session.advance(4);auto& vm=session.runtime();auto& ai=*session.ais()[0];auto& avm=*ai.runtime;auto real=[&](int value){return vm.real(jass::Real::fromInteger(value));};auto spawn=[&](const char* type,int x,int y){return vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000),vm.integer(int(ObjectData::code(type))),real(x),real(y),real(0)});};auto soldier=spawn("hfoo",9000,1500),carrier=spawn("nzep",8500,1500);auto fast=slow?spawn("hfoo",8500,1500):vm.handle("unit",0);auto unit=session.units().at(soldier.bits),ship=session.units().at(carrier.bits);if(slow)unit->moveSpeed=jass::Real::fromInteger(5);WorldPoint island{jass::Real::fromInteger(3599),jass::Real::fromInteger(2077)};if(session.world()->pathRegionsNear({unit->x,unit->y},island,unit->collision,pathMovement(unit->movementType),512)!=false)throw std::runtime_error("Island fixture unexpectedly reachable on foot");vm.invoke("SetUnitInvulnerable",std::array{soldier,vm.boolean(true)});if(slow)vm.invoke("SetUnitInvulnerable",std::array{fast,vm.boolean(true)});ai.assault.clear();ai.assault[unit->type]=slow?2:1;ai.captain.clear();ai.captain.insert(soldier.bits);if(slow)ai.captain.insert(fast.bits);avm.invoke("LoadZepWave",std::array{avm.integer(3599),avm.integer(2077)});if(!ai.zeppelinWave || !ai.zeppelinWave->passengers.contains(soldier.bits) || unit->combat.board!=carrier.bits || unit->route.empty())throw std::runtime_error("AI did not assign the soldier to approach transport");avm.invoke("AttackMoveXY",std::array{avm.integer(3599),avm.integer(2077)});bool boarded=false;double boardedAt=0;for(int n=0;n<(slow?1600:720);++n){session.advance(.25);if(!boarded && unit->transport==carrier.bits && !ship->cargo.empty()){boarded=true;boardedAt=session.simulationTime();}if(slow && n==184 && (!ai.zeppelinWave || ai.zeppelinWave->departing || session.units().at(fast.bits)->transport!=carrier.bits))throw std::runtime_error("Carrier abandoned a slow passenger after boarding a faster one");if(boarded && !ai.zeppelinWave && !unit->transport && std::hypot(number(unit->x)-3599,number(unit->y)-2077)<600){if(slow && (boardedAt<49 || session.units().at(fast.bits)->transport || std::hypot(number(session.units().at(fast.bits)->x)-3599,number(session.units().at(fast.bits)->y)-2077)>=600))throw std::runtime_error("Mixed transport did not retain both passengers through the long boarding interval");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS ai_island_transport_wave time="<<session.simulationTime()<<"\n";return;}}throw std::runtime_error("AI transport wave did not land on the island");
}
void islandPickup(const wchar_t* root,const wchar_t* map,int mode=0){
    Archives archives(root);archives.mountMap(map);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.audioSimulationClock();session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();session.advance(4);auto& vm=session.runtime();auto& ai=*session.ais()[0];auto& avm=*ai.runtime;auto real=[&](int value){return vm.real(jass::Real::fromInteger(value));};auto spawn=[&](const char* type,int x,int y){return vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000),vm.integer(int(ObjectData::code(type))),real(x),real(y),real(0)});};auto soldier=spawn("hfoo",3599,2077),carrier=spawn("nzep",8500,1500);auto second=mode>=3?spawn("hfoo",3700,2100):vm.handle("unit",0);std::vector<jass::Value> extra;if(mode==6)for(int i=0;i<7;++i)extra.push_back(spawn("hfoo",3450+i*40,2200));auto unit=session.units().at(soldier.bits),ship=session.units().at(carrier.bits);WorldPoint destination{jass::Real::fromInteger(9000),jass::Real::fromInteger(1500)};if(session.world()->pathRegionsNear({unit->x,unit->y},{ship->x,ship->y},unit->collision,pathMovement(unit->movementType),512)!=false)throw std::runtime_error("Pickup fixture unexpectedly reachable on foot");vm.invoke("SetUnitInvulnerable",std::array{soldier,vm.boolean(true)});vm.invoke("SetUnitInvulnerable",std::array{carrier,vm.boolean(true)});if(mode>=3)vm.invoke("SetUnitInvulnerable",std::array{second,vm.boolean(true)});ai.assault.clear();ai.assault[unit->type]=mode==6?9:mode>=3?2:1;ai.captain.clear();ai.captain.insert(soldier.bits);if(mode>=3)ai.captain.insert(second.bits);for(auto extraUnit:extra)ai.captain.insert(extraUnit.bits);avm.invoke("LoadZepWave",std::array{avm.integer(9000),avm.integer(1500)});if(!ai.zeppelinWave || !ai.zeppelinWave->passengers.contains(soldier.bits) || (mode>=3 && !ai.zeppelinWave->passengers.contains(second.bits)))throw std::runtime_error("AI did not assign a carrier to the isolated passengers");if(mode==6){if(session.cargoCapacity(carrier.bits)!=8 || ai.zeppelinWave->passengers.size()!=8 || ai.zeppelinWave->pickupQueued.size()!=7)throw std::runtime_error("Isolated pickup reservation exceeded transport capacity");std::cout<<"PASS ai_island_pickup_capacity\n";return;}if(mode==4){if(!vm.invoke("IssuePointOrder",std::array{second,vm.string("move"),real(3200),real(2050)}).bits)throw std::runtime_error("Queued passenger replacement order rejected");auto revision=session.units().at(second.bits)->combat.revision;avm.invoke("AttackMoveXY",std::array{avm.integer(9000),avm.integer(1500)});session.advance(2);if(!ai.zeppelinWave || ai.zeppelinWave->passengers.contains(second.bits) || !ai.zeppelinWave->passengers.contains(soldier.bits) || session.units().at(second.bits)->combat.revision!=revision)throw std::runtime_error("Queued passenger replacement did not preserve its new command");std::cout<<"PASS ai_queued_passenger_replacement\n";return;}if(mode==5){vm.invoke("SetUnitInvulnerable",std::array{soldier,vm.boolean(false)});vm.invoke("KillUnit",std::array{soldier});avm.invoke("AttackMoveXY",std::array{avm.integer(9000),avm.integer(1500)});bool carried=false;for(int n=0;n<1200;++n){session.advance(.25);auto u=session.units().at(second.bits);carried|=u->transport==carrier.bits;if(carried && !ai.zeppelinWave && !u->transport && std::hypot(number(u->x)-number(destination.x),number(u->y)-number(destination.y))<600){std::cout<<"PASS ai_pickup_after_passenger_death\n";return;}}throw std::runtime_error("Carrier did not continue with the next passenger after the first died");}if(mode==1){if(!vm.invoke("IssuePointOrder",std::array{carrier,vm.string("move"),real(8000),real(1500)}).bits)throw std::runtime_error("Carrier replacement order rejected");avm.invoke("AttackMoveXY",std::array{avm.integer(8000),avm.integer(1500)});if(ai.zeppelinWave || ship->currentOrder!=851986 || ship->route.empty())throw std::runtime_error("Wave cancellation interrupted the carrier replacement order");std::cout<<"PASS ai_pickup_cancel_preserves_replacement\n";return;}if(mode==2){auto deadline=ai.zeppelinWave->deadline;avm.invoke("AttackMoveXY",std::array{avm.integer(9000),avm.integer(1500)});ship->paused=true;while(ai.zeppelinWave && session.simulationTime()<deadline+3)session.advance(1);if(session.simulationTime()<deadline || ai.zeppelinWave || ship->cast || ship->currentOrder || !ship->route.empty())throw std::runtime_error("Timed-out pickup retained its carrier order");ship->paused=false;session.advance(2);if(ship->cast || ship->currentOrder || !ship->route.empty())throw std::runtime_error("Timed-out pickup resumed after pause");std::cout<<"PASS ai_pickup_timeout_cleans_order\n";return;}avm.invoke("AttackMoveXY",std::array{avm.integer(9000),avm.integer(1500)});bool boarded=false;for(int n=0;n<1200;++n){session.advance(.25);boarded|=unit->transport==carrier.bits && !ship->cargo.empty();if(boarded && !ai.zeppelinWave && !unit->transport && std::hypot(number(unit->x)-number(destination.x),number(unit->y)-number(destination.y))<600){if(mode==3 && (session.units().at(second.bits)->transport || std::hypot(number(session.units().at(second.bits)->x)-number(destination.x),number(session.units().at(second.bits)->y)-number(destination.y))>=600))throw std::runtime_error("Second isolated passenger was not delivered");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS ai_island_pickup_and_delivery time="<<session.simulationTime()<<"\n";return;}}throw std::runtime_error("Carrier did not collect and deliver the isolated passenger");
}
void meleeBuildRoute(const wchar_t* root,const wchar_t* map){
    auto real=[](float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));};Archives archives(root);archives.mountMap(map);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.audioSimulationClock();session.configure();PlayerSetup setup(info,session.config());if(!setup.control(1,SlotControl::ComputerNormal) || !setup.race(1,3))throw std::runtime_error("Cannot configure undead AI");session.applySetup(setup);session.startMain();std::shared_ptr<UnitState> builder;for(int n=0;n<960 && !builder;++n){session.advance(1./32);for(auto& [id,u]:session.units())if(u->owner==1 && u->buildOrder && ObjectData::name(u->buildOrder->type)=="uaod" && !u->route.empty()){builder=u;break;}}if(!builder)throw std::runtime_error("AI did not issue altar construction route");auto end=builder->route.back();auto savedSpeed=builder->moveSpeed;bool savedPathing=builder->pathing;builder->pathing=false;builder->moveSpeed=real(1);WorldPoint detour{builder->x,real(number(builder->y)+64)};builder->route.insert(builder->route.begin()+builder->waypoint,detour);auto index=builder->waypoint;session.advance(.5);if(!builder->buildOrder || builder->waypoint!=index || builder->route.size()<=index || builder->route[index].x.bits()!=detour.x.bits() || builder->route[index].y.bits()!=detour.y.bits() || builder->route.back().x.bits()!=end.x.bits() || builder->route.back().y.bits()!=end.y.bits())throw std::runtime_error("Construction discarded a valid avoidance route");WorldPoint invalid{real(number(builder->x)+1000),real(number(builder->y)+1000)};builder->route.back()=invalid;session.advance(.5);if(builder->route.empty() || (builder->route.back().x.bits()==invalid.x.bits() && builder->route.back().y.bits()==invalid.y.bits()))throw std::runtime_error("Construction retained a route to an invalid site");builder->pathing=savedPathing;builder->moveSpeed=savedSpeed;for(unsigned n=0;n<160;++n){session.advance(1);for(auto& [id,u]:session.units())if(u->owner==1 && ObjectData::name(u->type)=="uaod" && !u->construction && number(u->life)>0){if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS construction_route_and_altar_completion time="<<session.simulationTime()<<"\n";return;}}throw std::runtime_error("AI did not finish altar construction");
}
void meleeMine(const wchar_t* root,const wchar_t* map,unsigned race,const char* coverType){
    Archives archives(root);archives.mountMap(map);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.audioSimulationClock();session.configure();PlayerSetup setup(info,session.config());if(!setup.control(1,SlotControl::ComputerNormal) || !setup.race(1,race))throw std::runtime_error("Cannot configure melee AI race");session.applySetup(setup);session.startMain();session.advance(10);if(!session.ais()[1])throw std::runtime_error("Melee AI did not start");auto& vm=*session.ais()[1]->runtime;std::uint32_t cover=0;for(auto& [id,u]:session.units())if(u->owner==1 && ObjectData::name(u->type)==coverType && u->mineSource){cover=id;break;}if(!cover)throw std::runtime_error("Covered starting mine not found");auto mine=session.units().at(cover);auto base=session.units().at(mine->mineSource);int initial=base->resources;if(initial<=0 || mine->resources!=0 || std::bit_cast<int>(vm.invoke("GetMinesOwned").bits)!=1 || std::bit_cast<int>(vm.invoke("GetGoldOwned").bits)!=initial)throw std::runtime_error("AI mine queries did not use covered mine balance");session.advance(50);auto states=session.config().players[1].states;if(base->resources>=initial || states[15]<=0)throw std::runtime_error("Melee AI did not mine covered gold");if(std::bit_cast<int>(vm.invoke("GetGoldOwned").bits)!=base->resources)throw std::runtime_error("AI gold query did not follow mine depletion");int extracted=initial-base->resources;auto& mapvm=session.runtime();auto coverHandle=mapvm.handle("unit",cover);mapvm.invoke("SetResourceAmount",std::array{coverHandle,mapvm.integer(0)});if(vm.invoke("GetMinesOwned").bits || vm.invoke("GetGoldOwned").bits)throw std::runtime_error("Depleted covered mine remained available");mapvm.invoke("SetResourceAmount",std::array{coverHandle,mapvm.integer(73)});if(vm.invoke("GetMinesOwned").bits!=1 || vm.invoke("GetGoldOwned").bits!=73 || base->resources!=73)throw std::runtime_error("Restored covered mine balance was not detected");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS covered_mine race="<<race<<" extracted="<<extracted<<"\n";
}
